#include "../src/core.hpp"
#include <iostream>
#include <stdexcept>
#include <functional>
using namespace snow;
static int tests=0;
static void check(bool condition,const char*message){if(!condition)throw std::runtime_error(message);}
static void test(const char*name,std::function<void()>f){f();++tests;std::cout<<"PASS "<<name<<"\n";}
static Profile filled(double width=800,double maximum=48,bool rounded=false){Profile p(width,maximum,42,rounded);for(double x=0;x<=width;x+=4)p.deposit(x,100);return p;}
static Surface floorSurface(){return{bottomID,0,0,800,0,true,{{0,800}}};}
int main(){try{
 test("settings clamp invalid numbers",[]{Settings s;s.wind=900;s.brightness=-1;s.intensity=3;s.windowHeight=0;s.sanitize();check(s.wind==100&&s.brightness==0&&s.intensity==1&&s.windowHeight==4,"sanitize");});
 test("snow remains mounded at full capacity",[]{auto p=filled();auto mm=std::minmax_element(p.h.begin(),p.h.end());check(*mm.second-*mm.first>3,"mounds flattened");check(*mm.second<=48&&p.height(0)>0,"height/bottom edge");});
 test("rounded window ends and overflow",[]{auto p=filled(400,18,true);check(p.height(0)==0&&p.height(400)==0,"square edges");check(p.height(24)>p.height(4),"no taper");check(p.deposit(0,5)>0,"overflow missing");});
 test("profile resize preserves local position",[]{auto p=filled(400,18,true);double before=p.height(200);p.resize(600,18);check(std::abs(p.height(200)-before)<1e-8&&p.height(550)==0&&p.height(600)==0,"resize moved snow");});
 test("snow transfer conserves requested area",[]{auto p=filled();double a=p.available(200,50);double taken=p.take(200,50,137);check(std::abs(taken-137)<1e-6&&std::abs(a-p.available(200,50)-137)<1e-6,"mass changed");});
 test("clear range does not touch future snow",[]{auto p=filled();double before=p.height(700);check(p.clear(0,100)>0&&p.height(40)==0&&p.height(700)==before,"clearing scope");});
 test("wind/weather particle budget",[]{Settings s;s.weather=2;Simulation sim({800,600});sim.sync({},s,{});for(int i=0;i<1200;i++)sim.step(1./60,s,false);check(sim.particles.size()<=360&&sim.profiles.at(bottomID).h.size()<=2048,"unbounded simulation");});
 test("removed window profiles are pruned",[]{Settings s;s.bottom=false;Simulation sim({800,600});sim.sync({{10,100,200,400,0,false,{{0,400}}}},s,{10});sim.sync({},s,{});check(sim.profiles.empty(),"dead window retained");});
 test("deep snow gesture creates stable ball",[]{auto floor=floorSurface();std::vector<Surface>s{floor};std::map<uint64_t,Profile>p{{bottomID,filled()}};Game g;g.begin({100,3},1,s,p);g.drag({250,3},1.2,s,p);check(g.balls.size()==1&&g.balls[0].radius>6,"no rolled ball");g.end({250,3},2,s,p);for(int i=0;i<600;i++)g.step(1./60,s,p,{800,600});check(g.balls.size()==1&&g.balls[0].surface==bottomID,"ball fell through floor");});
 test("fast throw flies into glass and leaves a melting mark",[]{Game g;g.balls.push_back({9000,0,0,20,0,0,{100,200},{}});std::vector<Surface>s{floorSurface()};std::map<uint64_t,Profile>p{{bottomID,filled()}};g.begin({100,200},1,s,p);g.drag({220,320},1.2,s,p);g.end({220,320},1.21,s,p);check(g.balls.empty()&&g.flights.size()==1,"no glass flight");for(int i=0;i<30;i++)g.step(1./60,s,p,{800,600});check(g.flights.empty()&&g.marks.size()==1,"no impact");for(int i=0;i<330;i++)g.step(1./60,s,p,{800,600});check(g.marks.empty(),"mark does not melt");});
 test("holding removes throw impulse",[]{Game g;g.balls.push_back({9001,0,0,20,0,0,{100,200},{}});std::vector<Surface>s{floorSurface()};std::map<uint64_t,Profile>p{{bottomID,filled()}};g.begin({100,200},1,s,p);g.drag({220,320},1.2,s,p);g.end({220,320},2,s,p);check(length(g.balls[0].velocity)==0,"held ball was thrown");});
 test("three equal balls fit into snowman",[]{Game g;g.balls={{9100,bottomID,0,33,200,33,{200,33},{}},{9101,0,0,33,0,0,{400,80},{}},{9102,0,0,33,0,0,{600,80},{}}};std::vector<Surface>s{floorSurface()};std::map<uint64_t,Profile>p{{bottomID,Profile(800,48,42,false)}};g.begin({400,80},1,s,p);g.drag({205,99},1.2,s,p);g.end({205,99},2,s,p);auto top=g.balls[1].p.y+g.balls[1].radius;g.begin({600,80},3,s,p);g.drag({204,top+33},3.2,s,p);g.end({204,top+33},4,s,p);check(g.snowmen().size()==1&&g.balls[2].radius<g.balls[1].radius,"stack did not fit");});
 test("snowman falls intact after support clearing",[]{Game g;g.balls={{9200,bottomID,0,33,200,81,{200,81},{}},{9201,bottomID,9200,24,200,138,{200,138},{}},{9202,bottomID,9201,17,200,179,{200,179},{}}};std::vector<Surface>s{floorSurface()};std::map<uint64_t,Profile>p{{bottomID,Profile(800,48,42,false)}};for(int i=0;i<180;i++)g.step(1./60,s,p,{800,600});check(g.balls.size()==3&&g.snowmen().size()==1&&std::abs(g.balls[0].p.y-33)<.001,"snowman suspended/broken");});
 test("snowman without floor leaves no orphan",[]{Game g;g.balls={{9300,0,0,33,200,81,{200,81},{}},{9301,0,9300,24,200,138,{200,138},{}},{9302,0,9301,17,200,179,{200,179},{}}};for(int i=0;i<600;i++)g.step(1./60,{}, {},{800,600});check(g.balls.empty(),"orphaned head");});
 test("ball limit prevents snow expenditure",[]{Game g;for(int i=0;i<30;i++)g.balls.push_back({uint64_t(9400+i),0,0,6,0,0,{double(i*10),400},{}});auto profile=filled();std::map<uint64_t,Profile>p{{bottomID,profile}};std::vector<Surface>s{floorSurface()};g.begin({700,4},1,s,p);g.drag({730,4},1.2,s,p);check(g.balls.size()==30&&p[bottomID].h==profile.h,"limit consumed snow");});
 test("bucket clears at its leading edge",[]{Cleaner c;Settings s;auto p=filled();check(c.start(0),"start");c.step(1./60,800,s,&p);check(c.collected==0,"collected before arrival");for(int i=1;i<20;i++)c.step(1./60,800,s,&p);check(p.height(24)==0&&p.height(48)>0&&c.load()>0&&c.load()<=1,"bucket geometry");});
 test("wheel distance resets each pass",[]{Cleaner c;Settings s;auto p=filled();c.start(1);for(int i=0;i<60;i++)c.step(1./60,800,s,&p);check(std::abs(c.distance-160)<.001,"travel distance");c.clear();c.start(0);check(c.distance==0&&c.load()==0,"new pass reset");});
 test("automatic cleaner cooldown",[]{Cleaner c;Settings s;s.automaticCleaner=true;auto p=filled();c.step(1./30,800,s,&p);check(c.active,"auto threshold");c.clear();check(!c.start(0,true),"cooldown ignored");});
 test("zero intensity and reduce motion steady",[]{Settings s;s.garland=2;s.brightness=.6;s.intensity=0;check(light(0,3,s,false)==.6&&light(12,3,s,false)==.6,"zero intensity");s.intensity=1;check(light(1,3,s,true)==.6,"reduce motion");s.garland=0;check(light(1,3,s,false)==0&&light(1,3,s,false,true)>0,"tree independent of screen garland");});
 test("tree grows once and removes",[]{Settings s;Simulation sim({800,600});sim.growTree(false);check(sim.tree&&sim.treeGrowth==0,"initial growth");for(int i=0;i<90;i++)sim.step(1./60,s,false);check(sim.treeGrowth==1,"growth duration");sim.growTree(true);check(sim.treeGrowth==1,"reduced motion instant");sim.removeTree();check(!sim.tree&&sim.treeGrowth==0,"remove");});
 test("click immediately creates a snowball from accumulated snow",[]{Game g;std::vector<Surface>s{floorSurface()};std::map<uint64_t,Profile>p{{bottomID,filled()}};double before=p[bottomID].available(200,26);g.begin({200,4},1,s,p);check(g.balls.size()==1&&g.dragged==g.balls[0].id,"no immediate ball");check(std::abs(before-p[bottomID].available(200,26)-pi*36)<1e-6,"ball did not consume its area");});
 test("mitten lifts loose snow without launching at glass",[]{Game g;std::vector<Surface>s{floorSurface()};std::map<uint64_t,Profile>p{{bottomID,filled()}};g.begin({200,4},1,s,p,true);g.drag({400,250},1.1,s,p);g.end({400,250},1.11,s,p,false);check(g.balls.size()==1&&g.balls[0].loose&&g.flights.empty(),"loose snow became glass ball");});
 test("rapid stacking has priority over glass throw",[]{Game g;g.balls={{1,bottomID,0,33,200,33,{200,33},{}},{2,0,0,20,0,0,{500,300},{}}};std::vector<Surface>s{floorSurface()};std::map<uint64_t,Profile>p{{bottomID,Profile(800,48,42,false)}};g.begin({500,300},1,s,p);g.drag({204,86},1.2,s,p);g.end({204,86},1.21,s,p);check(g.balls.size()==2&&g.balls[1].support==1&&g.flights.empty(),"stack launched at glass");});
 test("all six tree layouts spread five enlarged trees without repetition",[]{HolidayTrees tree;tree.state=42;std::set<std::vector<double>>seen;std::vector<double>previous;for(int n=0;n<120;n++){tree.choose();auto poses=tree.poses({1728,1084},1,nullptr);std::vector<double>x;double maximum=0;for(auto p:poses){x.push_back(p.p.x);maximum=std::max(maximum,p.sy*270);}check(poses.size()==5&&maximum>124.9&&maximum<=125.001,"tree count/25 percent size");check(x.front()<1728*.2&&x.back()>1728*.8&&x[2]>1728*.35&&x[2]<1728*.65,"edge-only placement");check(x!=previous,"immediate layout repeat");seen.insert(x);previous=x;}check(seen.size()==6,"not six layouts");});
 test("tree artwork bounds fit short portrait and wide displays",[]{for(uint64_t seed=0;seed<100;seed++){HolidayTrees tree;tree.state=seed;for(int n=0;n<6;n++){tree.choose();for(auto size:std::vector<V>{{48,48},{320,180},{800,1400},{1280,96},{1280,128},{1728,1084},{5000,2000}}){double right=-1;for(auto p:tree.poses(size,1,nullptr)){double left=p.p.x-96*p.sx;check(left>=0&&p.p.x+96*p.sx<=size.x&&p.p.y+284*p.sy<=size.y,"tree outside display");check(left>right,"trees overlap");right=p.p.x+96*p.sx;}}}}});
 test("tree layout is stable between frames",[]{Settings s;Simulation sim({1728,1084},4);sim.growTree(true);auto before=sim.treePoses();for(int i=0;i<120;i++)sim.step(1./60,s,false);auto after=sim.treePoses();check(before.size()==after.size(),"count changed");for(size_t i=0;i<before.size();i++)check(before[i].p.x==after[i].p.x&&before[i].sy==after[i].sy,"layout jitter");});
 test("snowflake style size and material do not alter physics",[]{Settings plain,patterned;patterned.snowflakeStyle=1;patterned.snowflakeSize=3;patterned.appearance=1;Simulation a({800,600},77),b({800,600},77);a.sync({},plain,{});b.sync({},patterned,{});for(int i=0;i<300;i++){a.step(1./60,plain,false);b.step(1./60,patterned,false);}check(a.particles.size()==b.particles.size(),"style changes particle count");for(size_t i=0;i<a.particles.size();i++)check(a.particles[i].p.x==b.particles[i].p.x&&a.particles[i].p.y==b.particles[i].p.y&&a.particles[i].id==b.particles[i].id,"style changes flight/stable ID");});
 test("mitten pushes a mound while conserving area",[]{Settings s;Simulation sim({800,600});sim.sync({},s,{});sim.profiles[bottomID]=filled();auto area=[](const Profile&p){double a=0;for(auto h:p.h)a+=h*p.step();return a;};double before=area(sim.profiles[bottomID]),at=sim.profiles[bottomID].height(400);sim.sweep({400,at},1,s.limit(),{390,at});check(std::abs(area(sim.profiles[bottomID])-before)<1e-5,"mitten lost snow");check(sim.profiles[bottomID].height(400)<at,"source not pushed");});
 test("pushed window snow falls and settles below without fading",[]{Settings s;Simulation sim({800,3000});Surface window{12,100,2400,500,0,false,{{0,500}},12};sim.sync({window},s,{12});sim.profiles[12]=Profile(500,18,12,true);for(int x=0;x<=500;x+=4)sim.profiles[12].deposit(x,200);V p=window.point(498,sim.profiles[12].height(498));sim.sweep(p,1,s.limit(),p-V{12,0});check(!sim.particles.empty()&&sim.particles[0].area>0,"no edge snow");double area=sim.particles[0].area;uint64_t id=sim.particles[0].id;for(int i=0;i<150;i++)sim.step(1./60,s,false);auto it=std::find_if(sim.particles.begin(),sim.particles.end(),[&](auto&p){return p.id==id;});check(it!=sim.particles.end()&&it->area>0&&it->alpha>.8,"falling snow faded before landing");for(int i=0;i<600;i++)sim.step(1./60,s,false);double settled=0;for(double h:sim.profiles[bottomID].h)settled+=h*sim.profiles[bottomID].step();check(settled>=area*.99,"snow did not reach lower surface");});
 test("window support wraps its rounded physical corner",[]{Surface s{12,100,400,500,0,false,{{0,500}},12};check(std::abs(s.supportHeight(0)+12)<1e-8&&s.supportHeight(12)==0&&s.supportHeight(250)==0,"corner shape");V p=s.point(4,8),q=s.local(p);check(std::abs(q.x-4)<1e-8&&std::abs(q.y-8)<1e-8,"corner coordinates are not inverse");});
 test("bounded carry pool preserves area when quality decreases",[]{Simulation sim({800,600});for(int i=0;i<1000;i++)sim.particles.push_back({{400,500},40,0,2,.8,30,true,3,0,uint64_t(i+1)});sim.trim(360);double sum=0;for(auto p:sim.particles)sum+=p.area;check(sim.particles.size()==360&&std::abs(sum-3000)<1e-8,"budget discarded carried snow");});
 test("new natural snow does not flatten a hand-made mound",[]{auto p=filled();p.take(300,24,300);p.addArea(400,24,300);double before=p.height(400);p.deposit(400,1);check(p.height(400)>=before,"manual mound was erased");});
 test("clear removes glass snow and loose snow",[]{Game g;g.marks.push_back({{200,200},40,1,2});g.flights.push_back({{200,200},{400,300},20,0,1});g.balls.push_back({1,0,0,9,0,0,{100,200},{},true});g.clear();check(g.marks.empty()&&g.flights.empty()&&g.balls.empty(),"clear retained objects");});
 std::cout<<tests<<" tests passed\n";return 0;
 }catch(const std::exception&e){std::cerr<<"FAILED: "<<e.what()<<"\n";return 1;}}
